/* Default / Light Theme */
.alert-banner {
    background: linear-gradient(135deg, #E8F1FF, #DDEBFF);
    border-left: 5px solid #3B82F6;
    color: #1E3A8A;
    padding: 12px 16px;
    border-radius: 8px;
    margin: 12px 0;
    font-family: Arial, sans-serif;
    font-size: 14px;
    line-height: 1.5;
    position: relative;
    overflow: hidden;
    transition: color 0.3s, border-color 0.3s, box-shadow 0.3s;

    /* subtle pulse */
    animation: pulseGlow 2.5s infinite ease-in-out;
}

/* Dark Theme */
html.dark .alert-banner {
    background: linear-gradient(135deg, #1e293b, #0f172a); /* Latar belakang biru gelap / slate */
    color: #dbeafe; /* Teks biru muda terang */
    border-left-color: #60a5fa; /* Warna border sedikit diterangkan agar lebih "pop" di layar gelap */
}

/* Efek glow pulse - bisa dipakai untuk light dan dark mode */
@keyframes pulseGlow {
    0% {
        box-shadow: 0 0 0 rgba(59, 130, 246, 0.2);
    }
    50% {
        box-shadow: 0 0 12px rgba(59, 130, 246, 0.4);
    }
    100% {
        box-shadow: 0 0 0 rgba(59, 130, 246, 0.2);
    }
}

/* Efek bling (shimmer lewat sekali-sekali) - Light Mode */
.alert-banner::after {
    content: "";
    position: absolute;
    top: 0;
    left: -75%;
    width: 50%;
    height: 100%;
    background: linear-gradient(
        120deg,
        transparent,
        rgba(255, 255, 255, 0.6),
        transparent
    );
    transform: skewX(-20deg);
    animation: shimmer 3.5s infinite;
}

/* Efek bling - Dark Mode (Intensitas putihnya dikurangi agar tidak silau) */
html.dark .alert-banner::after {
    background: linear-gradient(
        120deg,
        transparent,
        rgba(255, 255, 255, 0.15), /* Opacity diturunkan dari 0.6 menjadi 0.15 */
        transparent
    );
}

@keyframes shimmer {
    0% {
        left: -75%;
    }
    100% {
        left: 125%;
    }
}

