        display: list-item !important;       /* Memastikan elemen tampil sebagai list */
        margin-bottom: 6px !important;       /* Memberi jarak antar poin */
        line-height: 1.5;
    }
    
    /* Menghilangkan margin bawah pada poin terakhir agar rapi */
    .instruction-banner ol li:last-child {
        margin-bottom: 0 !important;
    }

    /* Dark Theme (ketika class 'dark' ada di tag html) */
    html.dark .instruction-banner {
        background-color: #1e293b;  /* Latar belakang biru gelap / slate */
        color: #dbeafe;             /* Teks biru muda terang agar mudah dibaca */
        border-left-color: #60a5fa; /* Warna border diterangkan agar terlihat jelas di layar gelap */
    }


